export const BOOKS = sourceBooks.map((book, index) => ({
  ...book,
  timely: {
    ...book.timely,
    trendingScore: trendingBookIds.has(book.id)
      ? Math.max(book.timely.trendingScore, 80)
      : Math.min(book.timely.trendingScore, 74),
    adaptation: adaptationBookIds.has(book.id) ? book.timely.adaptation : null,
    seasonal: seasonalBookIds.has(book.id) ? book.timely.seasonal : null,
  },
  length: book.pages < 250 ? 'short' : book.pages <= 400 ? 'medium' : 'long',
  cover: coverPalettes[index % coverPalettes.length],
}));

